type Tab = "today" | "echo" | "stampbook";
type TaskStatus = "ready" | "active" | "completed" | "partial" | "continued";
type FocusStatus = "idle" | "running" | "paused";
type TaskKind = "reading" | "exercise" | "coding" | "offline" | "custom";
type TaskColor = "sage" | "peach" | "yellow";
