type SourceRef = { label: string; url: string; createdAt: number };
type StampBookState = { version: number; styleAssignments: Record<string, StampStyleChoice>; };
type Preferences = { focusMode: FocusMode; defaultFocusMinutes: number; reminderEnabled: boolean; echoTime: string; includeDiaryInAI: boolean; zhihuMatching: boolean; zhihuConnected: boolean; reduceMotion: boolean; theme: "paper"; memoryEnabled?: boolean; memoryIntroSeen?: boolean; backgroundOrganize?: boolean };
type PersistedState = { version: 5; demoData?: boolean; tasks: Task[]; focusSession: FocusSession; focusLedger: Record<string, number>; focusLogs: FocusLog[]; outcomes: Outcome[]; diaries: DiaryEntry[]; dailyEchoes: Record<string, DailyEchoDraft>; weeklyEchoes: WeeklyEchoDraft[]; notes: FootprintNote[]; workRecords: WorkRecord[]; milestones: Milestone[]; blockers: Blocker[]; experiments: TomorrowExperiment[]; sourceRef: SourceRef | null; methodNote: string; preferences: Preferences; stampStyles: Record<string, StampStyleChoice>; stampBook: StampBookState };

