  useEffect(() => { try { window.localStorage.setItem(STORAGE_KEY, JSON.stringify(state)); } catch { /* storage can be disabled in previews */ } }, [state]); useEffect(() => { if (state.focusSession.status !== "running") return; const timer = window.setInterval(() => setClockNow(Date.now()), 1000); return () => window.clearInterval(timer); }, [state.focusSession.status]); useEffect(() => { const screen = document.querySelector<HTMLElement>("[data-testid='device-screen']"); const update = () => setDesktopMode((screen?.clientWidth ?? window.innerWidth) >= 900); update(); const observer = screen && typeof ResizeObserver !== "undefined" ? new ResizeObserver(update) : null; if (observer && screen) observer.observe(screen); window.addEventListener("resize", update); return () => { observer?.disconnect(); window.removeEventListener("resize", update); }; }, []); useEffect(() => { if (echoDiary) { setDiaryDraft(echoDiary.text); setDiarySaved(true); } else { setDiaryDraft(""); setDiarySaved(false); } }, [echoDiary?.id, echoTargetDateKey]);
  useEffect(() => { document.querySelector<HTMLElement>(".app-screen")?.scrollTo({ top: 0 }); }, [tab, todayStage, stampBookView]);
  const notify = (message: string) => { setToast(message); window.setTimeout(() => setToast(""), 2400); };
  const remember = (input: { eventKey: string; taskId?: string; dateKey: string; userQuotes?: string[]; nextStep?: string; sourceIds?: string[] }) => { if (state.preferences.memoryEnabled === false || state.preferences.backgroundOrganize === false) return; void aiClient.memory(input).catch(() => {}); };
