  const toggleFocus = () => { const task = activeTask; if (!task) { notify("先选择一个未完成的步骤"); return; } const now = Date.now(); if (state.focusSession.status === "running") { setState((current) => { const settled = settleRunning(current, now); return { ...settled, focusSession: { ...settled.focusSession, activeTaskId: task.id, status: "paused", startedAt: null, resumeNote: settled.focusSession.resumeNote ?? "从这里继续" } }; }); setClockNow(now); notify("已暂停，投入时间已经保留"); return; } setState((current) => ({ ...current, focusSession: { activeTaskId: task.id, status: "running", startedAt: now, resumeNote: current.focusSession.resumeNote } })); setClockNow(now); notify(state.focusSession.status === "paused" ? "已接上这一小步" : "开始记录这一小步"); };
  const endFocus = () => { if (state.focusSession.status === "idle") return; const now = Date.now(); setState(current => settleRunning(current, now)); setTodayStage("plan"); setClockNow(now); notify("这段投入已收好，任务状态保持不变"); };
  const openOutcome = () => { if (!activeTask) { notify("先选择一项路线任务"); return; } keyboard.hide(); setOutcomeTaskId(activeTask.id); setOutcomeBody(""); setNextStepInput(state.focusSession.resumeNote ?? ""); setOutcomeKind(activeTask.kind === "exercise" ? "answer" : activeTask.kind === "coding" ? "file" : activeTask.kind === "offline" ? "self-report" : "summary"); setOutcomeClassification("completed"); setMilestoneCheck(Boolean(activeTask.milestoneId)); setOutcomeOpen(true); };
  const recordBlocker = (label: string) => { if (!activeTask) { notify("先选择正在进行的步骤"); return; } const now = Date.now(); const note: FootprintNote = { id: createId("note"), type: "blocker", title: "遇到一个卡点", body: label, color: "peach", dateKey: todayKey, createdAt: now, taskId: activeTask.id, pinned: false }; const blocker: Blocker = { id: createId("blocker"), taskId: activeTask.id, label, dateKey: todayKey, createdAt: now }; setState((current) => ({ ...current, blockers: [blocker, ...current.blockers], notes: [note, ...current.notes] })); setShowBlocker(false); notify(`已记录卡点：${label}`); };
