  const addTask = () => { const title = taskInput.trim(), expectedArtifact = artifactInput.trim(), planMinutes = Math.max(1, Math.min(180, Number.parseInt(taskMinutesInput, 10) || state.preferences.defaultFocusMinutes || 25)); if (!title || !expectedArtifact) { notify("请同时写下任务和完成后要留下的成果"); return; } const task: Task = { id: createId("task"), title, subject: "自定义", duration: `${planMinutes} 分钟`, planMinutes, actualMs: 0, status: "ready", color: "yellow", kind: "custom", expectedArtifact, revisionCount: 0 }; setState((current) => ({ ...current, tasks: [...current.tasks, task], focusLedger: { ...current.focusLedger, [task.id]: 0 } })); setTaskInput(""); setArtifactInput(""); setTaskMinutesInput(String(state.preferences.defaultFocusMinutes || 25)); setShowComposer(false); notify("已加入今日路线"); };
  const saveDiary = () => { const text = diaryDraft.trim(); if (!text) { notify("写下一两句真实发生的事"); return; } const now = Date.now(); const eventKey = `diary:${echoTargetDateKey}`; setState((current) => { const existing = current.diaries.find((entry) => entry.dateKey === echoTargetDateKey); const entry: DiaryEntry = existing ? { ...existing, text, updatedAt: now } : { id: createId("diary"), dateKey: echoTargetDateKey, text, createdAt: now, updatedAt: now }; return { ...current, diaries: existing ? current.diaries.map((item) => item.id === existing.id ? entry : item) : [entry, ...current.diaries] }; }); remember({ eventKey, dateKey: echoTargetDateKey, userQuotes: [text] }); queueAutoStamp(echoTargetDateKey, eventKey); setDiarySaved(true); notify(echoTargetDateKey === todayKey ? "今天的记录已保存" : `${echoTargetDateKey} 的记录已保存`); };
