  const renderTaskRow = (task: Task, index: number) => { const progress = task.planMinutes ? Math.min(100, Math.round((taskElapsed(task.id) / (task.planMinutes * 60_000)) * 100)) : 0; return <div data-testid={`task-row-${task.id}`} data-task-drop={task.id} className={`task-row ${task.status} ${task.color} ${draggingTaskId === task.id ? "is-dragging" : ""} ${dragOverTaskId === task.id && draggingTaskId !== task.id ? "is-drag-over" : ""}`} key={task.id} role="button" tabIndex={0} onClick={() => { if (!suppressTaskClickRef.current) selectTask(task.id); }} onKeyDown={(event) => { if (event.target === event.currentTarget && (event.key === "Enter" || event.key === " ") && !suppressTaskClickRef.current) { event.preventDefault(); selectTask(task.id); } }}><button type="button" className="task-drag-handle" data-scroll-drag="ignore" aria-label={`拖动排序：${task.title}`} onClick={(event) => event.stopPropagation()} onPointerDown={(event) => beginTaskDrag(event, task.id)} onPointerMove={moveTaskDrag} onPointerUp={endTaskDrag} onPointerCancel={endTaskDrag}>⠿</button><span className="route-node">{task.status === "completed" ? <CheckIcon /> : index + 1}</span><span className="task-copy"><strong>{task.title}</strong><small><span className="activity-dot" style={{ background: activityColor(task.subject) }} aria-hidden="true" />{task.subject} · {task.duration}</small><em>准备留下：{task.expectedArtifact}</em></span><span className="task-state"><span>{task.status === "active" ? "进行中" : task.status === "completed" ? "已完成" : task.status === "partial" ? "部分完成" : task.status === "continued" ? "待继续" : "未开始"}</span><i><b style={{ width: `${progress}%` }} /></i><small>{progress}% · {formatTaskDuration(taskElapsed(task.id))}</small></span><button type="button" className="task-delete-button" aria-label={`删除任务：${task.title}`} onClick={(event) => { event.stopPropagation(); deleteTask(task.id); }}>×</button></div>; };

